# Let's try the McGee graph using LCF notation
# LCF: [12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12]

n = 24
lcf = [12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12, -12, 7, -7, 12]

# Build adjacency list
adj = {i: [] for i in range(n)}

# Cycle edges
for i in range(n):
    adj[i].append((i+1) % n)
    adj[(i+1) % n].append(i)

# LCF edges
for i in range(n):
    j = (i + lcf[i]) % n
    if j not in adj[i]:
        adj[i].append(j)
    if i not in adj[j]:
        adj[j].append(i)

# Build edge list
edges = []
for u in range(n):
    for v in adj[u]:
        if u < v:
            edges.append((u, v))

print("Number of edges:", len(edges))

# Check degrees
degrees = [len(adj[u]) for u in range(n)]
print("Degrees:", degrees)
print("Min degree:", min(degrees), "Max degree:", max(degrees))

# Check connectivity
from collections import deque
visited = set()
queue = deque([0])
visited.add(0)
while queue:
    u = queue.popleft()
    for v in adj[u]:
        if v not in visited:
            visited.add(v)
            queue.append(v)
print("Connected:", len(visited) == n)

# Compute girth
import sys

def compute_girth(adj, n):
    girth = sys.maxsize
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < girth:
                        girth = cycle_len
    return girth if girth != sys.maxsize else -1

girth = compute_girth(adj, n)
print("Girth:", girth)

# Check colorability
def is_colorable(adj, n, k):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

print("3-colorable:", is_colorable(adj, n, 3))
print("4-colorable:", is_colorable(adj, n, 4))
print("5-colorable:", is_colorable(adj, n, 5))

