import random
from collections import deque

def compute_girth(adj, n):
    """Compute girth using BFS from each vertex."""
    girth = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < girth:
                        girth = cycle_len
    return girth if girth != float('inf') else -1

def is_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking."""
    colors = [-1] * n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    pos = {v: i for i, v in enumerate(order)}

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def greedy_girth_construction(n, target_edges, min_girth, max_degree=None):
    """Greedily add edges while maintaining girth constraint."""
    adj = {i: [] for i in range(n)}
    edges = []

    # Generate all possible edges
    all_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_edges)

    for u, v in all_edges:
        if max_degree is not None:
            if len(adj[u]) >= max_degree or len(adj[v]) >= max_degree:
                continue

        # Try adding edge (u, v)
        adj[u].append(v)
        adj[v].append(u)

        g = compute_girth(adj, n)
        if g >= min_girth or g == -1:
            edges.append((u, v))
            if len(edges) >= target_edges:
                return edges, adj
        else:
            # Remove edge
            adj[u].remove(v)
            adj[v].remove(u)

    return edges, adj

# Try multiple times with different random seeds
for seed in range(100):
    random.seed(seed)
    edges, adj = greedy_girth_construction(24, 33, 7, max_degree=4)
    if len(edges) >= 33:
        g = compute_girth(adj, 24)
        c5 = is_colorable(adj, 24, 5)
        print(f"Seed {seed}: {len(edges)} edges, girth {g}, 5-colorable: {c5}")
        if g >= 7 and c5:
            print("Found valid graph!")
            print("Edges:", sorted(edges))
            break
